// M6: settings-card RPC (decision 1 = Plan B; transport reworked in v1.2.1, C21).
//
// Host registers an exact Fetch route under /api via ctx.inject(['connection'], ...)
// once the connection service mounts; the web card calls
// connection.rpc.call('/api', 'heartbeat', { endpoint, ...payload }).
// (The original custom channel '/heartbeat' via rpc.handle() is unusable on
// DSH 0.1.5+: cordis pins the service's this.ctx to the provider context, so
// handle()'s internal owner.webServer.register always fails strict resolution.)
// Bindings authority = data/settings/bindings.json (decision 2); the card is
// just another client of the same host logic the CLI uses.
// Every endpoint runs inside the workspace guard; results are {ok,value} or
// {ok:false,error:{code,message,details}}. Verbs are dispatched through a Map
// and, when the host's /api gate is missing, only GATE_SAFE_ENDPOINTS serve
// (⑦A / HB-19, 2026-10-17).

import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import type { OrchestratorDeps } from './core/orchestrator.js';
import { getLastBeat, homeSessionId, resetHomeSession } from './core/orchestrator.js';
import { appendAuditLine } from './core/audit-log.js';
import type { UiConfig } from './config/ui-config.js';
import type { PathGuard } from './core/path-guard.js';
import { dshHomeDir } from './core/paths.js';
import type { WorkspacePaths } from './core/paths.js';
import { inQuietHours, readSentState } from './gate/gate.js';
import {
  activeSeeds,
  archivedSeeds,
  archiveSeedById,
  deleteSeed,
  loadPool,
  restoreSeed,
  seedsFilePath,
} from './seeds/pool.js';
import { loadProfile, profileFilePath } from './profile/store.js';
import { buildDigest } from './profile/digest.js';
import { ledgerFilePath } from './ledger/ledger.js';
import { EXCERPT_HEADER, excerptFilePath } from './excerpt/excerpt.js';
import { listWeeklyReports, readWeeklyReport } from './weekly/report.js';
import { addBinding, loadBindings, removeBinding } from './core/bindings.js';
import { addInterest, readEffective, removeInterest, setWanderWindows } from './browse/interests-edit.js';
import { writeText } from './vault/vault.js';
import { readStatus } from './statusbar/store.js';
import { loadTimeInjectState } from './statusbar/time-inject.js';
import type { Policy } from './config/schema.js';

/** Exact Fetch route under /api (C21: custom rpc.handle channels are unusable
 * under 0.1.5's strict cordis service resolution — see installHeartbeatRpc). */
export const RPC_ROUTE_PATH = '/api/heartbeat';

/**
 * ⑦A (2026-10-17 review, tightening H-41): the host's `/api` prefix gate is the
 * only authentication this route has — the plugin holds no credential of its own.
 * When that gate cannot be found the route fails closed: every verb is refused
 * except this short list of read-only, low-sensitivity ones (liveness plus what
 * the settings card needs to render). H-41+HB-19 refused six "destructive" verbs
 * and served everything else, which left every memory-bearing read —
 * `profile.digest`, `profile.partitions`, `seeds.list`, `interests.list`,
 * `weekly.get`, `migrate.export` — open to anything that could POST to loopback.
 */
const GATE_SAFE_ENDPOINTS = new Set([
  'status',
  'config.get',
  'sessions.list',
  'bindings.get',
  'weekly.list',
]);

interface RpcDeps {
  ctx: OrchestratorDeps['ctx'] & {
    inject(services: string[], callback: (scoped: unknown) => void): void;
  };
  paths: WorkspacePaths;
  guard: PathGuard;
  policy: Policy;
  /** Card-edited rhythm values (v1.7.0): live view getter + persist-and-apply setter. */
  ui: {
    get(): {
      intervalMin: number;
      maxDailySend: number;
      timeInjectMin: number;
      statusbar: boolean;
      idleMode: boolean;
      tokenSaver: boolean;
      psyEnabled: boolean;
    };
    set(patch: UiConfig & { psyEnabled?: boolean }): void;
  };
}

type RpcResult = { ok: true; value: unknown } | { ok: false; error: { code: string; message: string; details: Record<string, never> } };

const ok = (value: unknown): RpcResult => ({ ok: true, value });
const err = (code: string, message: string): RpcResult => ({ ok: false, error: { code, message, details: {} } });

let cachedVersion: string | null = null;
/** Plugin version for the card's status block (read once from package.json). */
function pluginVersion(paths: WorkspacePaths): string {
  if (cachedVersion) return cachedVersion;
  try {
    const pkg = JSON.parse(fs.readFileSync(path.join(paths.packageRoot, 'package.json'), 'utf8')) as { version?: string };
    cachedVersion = typeof pkg.version === 'string' ? pkg.version : 'unknown';
  } catch {
    cachedVersion = 'unknown';
  }
  return cachedVersion;
}

/** 素材池生命周期的审计出口（v1.9.0）：卡片上的归档/恢复/删除也留下痕迹。 */
function seedAuditSink(paths: WorkspacePaths): (entry: Record<string, unknown>) => void {
  return (entry) => {
    try {
      appendAuditLine(paths.logsDir + '/heartbeat.jsonl', entry);
    } catch { /* audit must never break the RPC call */ }
  };
}

/** 兴趣/时段卡片编辑的审计留痕（成功才记；失败原因走 RPC err 回给卡片）。 */
function auditInterests(paths: WorkspacePaths, action: string, r: { ok: boolean }, detail: unknown): void {
  try {
    appendAuditLine(paths.logsDir + '/heartbeat.jsonl', {
      event: `interests_${r.ok ? 'edit' : 'edit_failed'}`,
      action,
      detail: typeof detail === 'string' ? detail.slice(0, 80) : null,
    });
  } catch { /* audit must never break the RPC call */ }
}

/** Session titles from the host's projection cache. Titles are host data — the
 * client card merges them (client.js `nameOf`: title || id prefix).
 *
 * DSH 0.1.2 writes ONE RECORD PER SESSION under
 * `~/.dsh/storages/session_projcache/sessions/<sessionId>.json`
 * (`record.rows.title.val`). The single-file `session_projcache.json` we used
 * before is the older aggregate layout and goes stale: a session created after
 * the upgrade is simply absent from it, so `title` came back null and the card
 * printed the raw session id. Read the per-record layout FIRST, keep the
 * aggregate only as a legacy fallback. */
function loadSessionTitles(): Record<string, string> {
  const titles: Record<string, string> = {};
  const take = (id: string, value: unknown): void => {
    const t = value as { rows?: { title?: { val?: unknown } }; title?: { val?: unknown } } | undefined;
    const row = t?.rows?.title ?? t?.title;
    if (row && typeof row.val === 'string' && row.val && !titles[id]) titles[id] = row.val;
  };
  // 1) per-record layout (current).
  try {
    const dir = path.join(dshHomeDir(), 'storages', 'session_projcache', 'sessions');
    for (const file of fs.readdirSync(dir)) {
      if (!file.endsWith('.json')) continue;
      const id = file.slice(0, -'.json'.length);
      if (!id.startsWith('session-')) continue;
      try {
        const record = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8')) as { record?: unknown };
        take(id, record.record);
      } catch { /* skip a record we cannot read */ }
    }
  } catch { /* no per-record dir on older hosts */ }
  // 2) legacy aggregate fallback.
  try {
    const raw = JSON.parse(fs.readFileSync(path.join(dshHomeDir(), 'storages', 'session_projcache.json'), 'utf8')) as unknown;
    const walk = (node: unknown): void => {
      if (!node || typeof node !== 'object') return;
      for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
        if (key.startsWith('session-') && value && typeof value === 'object') {
          // Title lives at <session>.rows.title.val (host title service); the
          // val may be null while the title is still being generated.
          take(key, value);
        }
        walk(value);
      }
    };
    walk(raw);
    return titles;
  } catch {
    return titles;
  }
}

/** Host-side session registry (`~/.dsh/storages/workspace.json`) → the set of
 * session ids the USER actually sees in the sidebar.
 *
 * A persisted session is user-visible iff it belongs to some workspace's
 * `sessionIds` and is not in `archivedSessionIds`. Two exclusions fall out of
 * this for the bind picker (2026-09-30 user request):
 * - **archived** sessions (explicit `archivedSessionIds`, prefix formats are
 *   mixed on disk — some entries carry `session-`, some don't — so match
 *   both forms);
 * - **subagent child sessions**, which never join any workspace's
 *   `sessionIds` (observed: they only ever land in the archive list).
 *
 * Fail-open: a missing/corrupt registry returns `registryFound: false` and
 * the caller shows everything — an unreadable registry must not blank the
 * picker. The heartbeat home is always shown regardless (caller-side). */
export function loadVisibleSessionIds(registryFile?: string): { visible: Set<string>; registryFound: boolean } {
  try {
    const file = registryFile ?? path.join(dshHomeDir(), 'storages', 'workspace.json');
    const j = JSON.parse(fs.readFileSync(file, 'utf8')) as {
      global?: { archivedSessionIds?: unknown };
      tables?: { workspaces?: Record<string, { sessionIds?: unknown }> };
    };
    const archived = new Set(
      (Array.isArray(j.global?.archivedSessionIds) ? (j.global!.archivedSessionIds as unknown[]) : [])
        .map((s) => String(s)),
    );
    const isArchived = (id: string): boolean =>
      archived.has(id) || archived.has(id.replace(/^session-/, ''));
    const visible = new Set<string>();
    for (const ws of Object.values(j.tables?.workspaces ?? {})) {
      const ids = Array.isArray(ws?.sessionIds) ? (ws.sessionIds as unknown[]) : [];
      for (const raw of ids) {
        const id = String(raw);
        if (!isArchived(id)) visible.add(id);
      }
    }
    return { visible, registryFound: true };
  } catch {
    return { visible: new Set(), registryFound: false };
  }
}

/** One RPC verb: payload in, envelope out. `guard` / `paths` / `policy` / `deps`
 *  come from the closure built by {@link buildEndpoints}. */
type Endpoint = (p: Record<string, unknown>) => RpcResult | Promise<RpcResult>;

/**
 * H-36: the endpoint table. This used to be a single `switch` at the bottom of
 * the route handler — 22 verbs and ~250 lines, with the guest list (which
 * endpoints exist) tangled up with the machinery (envelope validation, the
 * catch-all error wrapper). Adding a verb is now one entry here; the wrapper
 * stays in one place.
 */
function buildEndpoints(deps: Omit<RpcDeps, 'ctx'>, isLive: (sessionId: string) => boolean): Record<string, Endpoint> {
  const { guard, paths, policy } = deps;
  return {
    async status() {
      const now = Date.now();
      const sent = readSentState(guard, paths, now);
      const beat = getLastBeat();
      // M7 statusbar block (§17.8): store + throttle-state + live flags.
      let lastTimeInjectAt: number | null = null;
      try {
        const state = loadTimeInjectState(guard, paths.dataDir);
        for (const v of Object.values(state)) {
          if (typeof v === 'number' && v > (lastTimeInjectAt ?? 0)) lastTimeInjectAt = v;
        }
      } catch { /* missing state file = never injected */ }
      let flags = { statusbarEnabled: true, timeInjectMin: 25, idleMode: false };
      try {
        const { getRuntime } = await import('./core/runtime.js');
        const f = getRuntime().flags;
        flags = { statusbarEnabled: f.statusbarEnabled(), timeInjectMin: f.timeInjectMin(), idleMode: f.idleMode() };
      } catch { /* pre-init: report defaults */ }
      return ok({
        now: new Date(now).toISOString(),
        version: pluginVersion(paths),
        intervalMin: policy.heartbeat.intervalMin,
        idleMode: policy.heartbeat.idleMode,
        cap: { used: sent.items.length, max: policy.gate.maxDailySend },
        quiet: inQuietHours(policy, now),
        lastBeat: beat,
        homeSessionId: homeSessionId(guard, paths),
        bindings: loadBindings(guard, paths.settingsDir).bindings.length,
        statusbar: {
          enabled: flags.statusbarEnabled,
          timeInjectMin: flags.timeInjectMin,
          lastStatus: readStatus(guard, paths),
          lastTimeInjectAt: lastTimeInjectAt === null ? null : new Date(lastTimeInjectAt).toISOString(),
        },
      });
    },

    'sessions.list'() {
      const root = path.join(dshHomeDir(), 'sessions');
      const bindings = loadBindings(guard, paths.settingsDir).bindings;
      const home = homeSessionId(guard, paths);
      const titles = loadSessionTitles();
      // Bind picker visibility: hide archived and subagent sessions
      // (2026-09-30 user request). Fail-open when the registry is
      // unreadable; the home is always listed.
      const { visible, registryFound } = loadVisibleSessionIds();
      const out: Record<string, unknown>[] = [];
      if (fs.existsSync(root)) {
        for (const slug of fs.readdirSync(root)) {
          for (const id of fs.readdirSync(path.join(root, slug))) {
            if (registryFound && id !== home && !visible.has(id)) continue;
            const binding = bindings.find((b) => b.sessionId === id);
            out.push({
              id,
              title: titles[id] ?? null,
              cwdSlug: slug,
              live: isLive(id),
              home: id === home,
              deliver: binding?.deliver ?? false,
              observe: binding?.observe ?? false,
            });
          }
        }
      }
      return ok({ sessions: out });
    },

    'bindings.get': () => ok(loadBindings(guard, paths.settingsDir)),

    'bindings.add'(p) {
      const id = String(p.sessionId ?? '');
      if (!id.startsWith('session-')) return err('bad-request', 'sessionId must look like session-...');
      const home = homeSessionId(guard, paths);
      if (id === home) return err('bad-request', '该会话是心跳正身，无需绑定（决策轮次固定发生在正身）');
      // Callers send BOTH flags explicitly (the card's per-flag toggles), so
      // this stays a full-state write: deliver defaults on, observe off.
      const b = addBinding(guard, paths.settingsDir, id, {
        deliver: p.deliver !== false,
        observe: p.observe === true,
      });
      return ok(b);
    },

    'bindings.remove'(p) {
      const id = String(p.sessionId ?? '');
      const removed = removeBinding(guard, paths.settingsDir, id);
      // H-09/H-45: one shared release path — gate.json, the home_reset audit
      // line and the orchestrator's cached agent — instead of an inline delete
      // that silently left the in-memory home behind.
      const homeReset = resetHomeSession(guard, paths, id);
      return ok({ removed, homeReset });
    },

    'seeds.list'() {
      const db = loadPool(guard, seedsFilePath(paths.dataDir));
      return ok({
        active: activeSeeds(db),
        archived: archivedSeeds(db),
        cap: policy.seeds.maxActive,
      });
    },

    'seeds.archive'(p) {
      const s = archiveSeedById(guard, seedsFilePath(paths.dataDir), String(p.id ?? ''), 'completed', Date.now(), seedAuditSink(paths));
      return s ? ok(s) : err('not-found', 'active seed not found');
    },

    'seeds.restore'(p) {
      const r = restoreSeed(guard, seedsFilePath(paths.dataDir), policy, String(p.id ?? ''), Date.now(), seedAuditSink(paths));
      return r.ok ? ok(r.seed) : err('restore-failed', r.reason);
    },

    'seeds.delete'(p) {
      return ok({ deleted: deleteSeed(guard, seedsFilePath(paths.dataDir), String(p.id ?? ''), seedAuditSink(paths)) });
    },

    // ── 兴趣范围 / 浏览时段（v1.4.0；首编继承出厂，见 interests-edit.ts）──
    'interests.list': () => ok(readEffective(paths)),

    'interests.add'(p) {
      const r = addInterest(guard, paths, String(p.text ?? ''));
      auditInterests(paths, 'add', r, p.text);
      return r.ok ? ok(r.doc) : err('bad-request', r.reason ?? 'add failed');
    },

    'interests.remove'(p) {
      const r = removeInterest(guard, paths, String(p.text ?? ''));
      auditInterests(paths, 'remove', r, p.text);
      return r.ok ? ok(r.doc) : err('not-found', r.reason ?? 'remove failed');
    },

    'interests.setWindows'(p) {
      const r = setWanderWindows(guard, paths, p.windows);
      auditInterests(paths, 'set-windows', r, JSON.stringify(p.windows ?? null));
      return r.ok ? ok(r.doc) : err('bad-request', r.reason ?? 'setWindows failed');
    },

    'config.get': () => ok(deps.ui.get()),

    'config.set'(p) {
      const patch = p as UiConfig;
      if (!patch || typeof patch !== 'object' || Array.isArray(patch)) {
        return err('bad-request', 'config.set needs a patch object');
      }
      const keys = Object.keys(patch).filter((k) =>
        ['intervalMin', 'maxDailySend', 'timeInjectMin', 'statusbar', 'idleMode', 'tokenSaver', 'psyEnabled'].includes(k),
      );
      if (keys.length === 0) return err('bad-request', 'config.set has no recognized field');
      try {
        deps.ui.set(patch);
      } catch (e) {
        return err('bad-request', String(e).slice(0, 120));
      }
      appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), { event: 'ui_config_set', keys });
      return ok(deps.ui.get());
    },

    'profile.digest'() {
      const d = buildDigest(guard, paths, policy, {});
      return ok({
        tact: d.tact,
        topic: d.topic,
        wander: d.wander,
        withinBudget: d.withinBudget,
        // v2.0 (item 6): the card shows the budget and what the caps dropped.
        totalChars: d.totalChars,
        budgetChars: d.budgetChars,
        omitted: d.omitted,
      });
    },

    'profile.partitions'() {
      // v2.0 (item 6): the card shows ONE partition at a time, entry by entry.
      // The digest view was a wall of text and never showed what the profile
      // actually holds. Read-only, same data profile.export walks.
      const doc = loadProfile(guard, profileFilePath(paths.dataDir));
      const partitions: Record<string, { total: number; valid: number; entries: Record<string, unknown>[] }> = {};
      for (const part of ['interest', 'projects', 'comm', 'psy'] as const) {
        const all = doc.partitions[part]?.entries ?? [];
        const valid = all.filter((e) => e.validTo === null);
        partitions[part] = {
          total: all.length,
          valid: valid.length,
          entries: valid
            .slice()
            .sort((a, b) => b.confidence - a.confidence || (a.updatedAt < b.updatedAt ? 1 : -1))
            .map((e) => ({
              id: e.id,
              topic: e.topic,
              subTopic: e.subTopic,
              content: e.content,
              confidence: e.confidence,
              temporal: e.temporal,
              updatedAt: e.updatedAt,
              lowActivity: e.lowActivity === true,
            })),
        };
      }
      return ok({ partitions });
    },

    'profile.export'() {
      const doc = loadProfile(guard, profileFilePath(paths.dataDir));
      const lines = [`# 画像导出 ${new Date().toISOString()}`, ''];
      for (const part of ['interest', 'projects', 'comm', 'psy'] as const) {
        lines.push(`## ${part}`);
        for (const e of doc.partitions[part]!.entries) {
          if (e.validTo !== null) continue;
          lines.push(`- [${e.topic}/${e.subTopic}] ${e.content} (conf ${e.confidence.toFixed(2)}, ${e.temporal})`);
        }
      }
      const out = path.join(paths.exportsDir, `profile-export-${Date.now()}.md`);
      writeText(guard, out, lines.join('\n') + '\n');
      return ok({ path: out });
    },

    'ledger.open'() {
      const f = ledgerFilePath(paths.dataDir);
      if (!fs.existsSync(guard.assert(f))) fs.writeFileSync(f, '# 账本\n', 'utf8');
      spawn('cmd', ['/c', 'start', '', f], { detached: true, stdio: 'ignore' }).unref();
      return ok({ path: f });
    },

    'excerpt.open'() {
      const f = excerptFilePath(paths.dataDir);
      if (!fs.existsSync(guard.assert(f))) fs.writeFileSync(f, EXCERPT_HEADER, 'utf8');
      spawn('cmd', ['/c', 'start', '', f], { detached: true, stdio: 'ignore' }).unref();
      return ok({ path: f });
    },

    'weekly.list': () => ok({ reports: listWeeklyReports(guard, paths.dataDir, policy.weekly.keepReports) }),

    'weekly.get'(p) {
      const file = String(p.file ?? '');
      const rep = readWeeklyReport(guard, paths.dataDir, file);
      if (!rep) return err('bad-request', `no such report: ${file}`);
      return ok(rep);
    },

    async 'migrate.export'(p) {
      // Card-side export (v1.8.0): same container as the CLI. The
      // passphrase lives only in this call — never audited, never logged.
      const passphrase = String(p.passphrase ?? '');
      if (!passphrase) return err('bad-request', '需要设置口令');
      const { collectMigrationEntries, encryptContainer } = await import('./vault/migrate.js');
      const { entries } = collectMigrationEntries(guard, paths);
      if (entries.length === 0) return err('bad-request', '没有可打包的记忆文件（data/ 是空的）');
      const out = path.join(paths.exportsDir, `heartbeat-memory-${new Date().toISOString().slice(0, 10)}.hbmig`);
      writeText(guard, out, encryptContainer(entries, passphrase));
      appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), { event: 'migrate_export', files: entries.length });
      return ok({ path: out, count: entries.length });
    },

    async 'migrate.import'(p) {
      const passphrase = String(p.passphrase ?? '');
      const file = String(p.file ?? '');
      if (!passphrase || !file) return err('bad-request', '需要容器路径与口令');
      const { decryptContainer, applyMigrationEntries } = await import('./vault/migrate.js');
      let text: string;
      try {
        // Read-only from a user-chosen path (likely OUTSIDE data/); the
        // path guard still gates every file we WRITE back.
        text = fs.readFileSync(file, 'utf8');
      } catch {
        return err('bad-request', `读不到迁移包：${file}`);
      }
      let container: ReturnType<typeof decryptContainer>;
      try {
        container = decryptContainer(text, passphrase);
      } catch (e) {
        return err('bad-request', String(e instanceof Error ? e.message : e));
      }
      const result = applyMigrationEntries(guard, paths, container.files);
      appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), {
        event: 'migrate_import', restored: result.restored.length, backedUp: result.backedUp.length, skipped: result.skipped.length,
        rolledBack: result.rolledBack?.length ?? 0, error: result.error ?? null,
      });
      // HB-06: an import that wrote nothing is a failure, not a cheerful ok with
      // the reason buried in the payload.
      if (result.error) return err('migrate-failed', result.error);
      return ok(result);
    },
  };
}

export function installHeartbeatRpc(
  ctx: OrchestratorDeps['ctx'] & { inject(services: string[], callback: (scoped: unknown) => void): void },
  deps: Omit<RpcDeps, 'ctx'>,
): void {
  // ── 0.1.5 适配（C21）─────────────────────────────────────────────────
  // 自定义通道 rpc.handle('/heartbeat') 在 0.1.5 的 cordis 严格服务解析下不可
  // 用：Service 把 this.ctx 固定在 client-connection 自己的上下文（其模块
  // inject 只有 ['credentials']），handle() 内部 owner.webServer.register 是在
  // 别人的 fiber 上读 webServer → `cannot get property "webServer" without
  // inject`，调用方怎么声明都救不了（现场取证 2026-09-12：合并 inject 三件套
  // + effect 包裹仍是这个错）。改走 connection.fetch.register()：在 /api 下注册
  // 精确路由，只写 connection 内部路由表、不碰任何其他服务；0.1.2 与 0.1.5 的
  // /api 共享处理器都先查精确路由再落 interceptor，两代宿主通用。浏览器认证
  // 由 /api 前缀的 requestRejection 统一把关。客户端相应改为
  // rpc.call('/api', 'heartbeat', { endpoint, ...args })。
  ctx.inject(['connection'], (scoped: unknown) => {
    const remoteCtx = scoped as {
      connection: {
        fetch: { register(route: {
          path: string;
          methods: string[];
          requestBody?: string;
          fetch(request: Request): Promise<Response>;
        }): unknown };
      };
      agents: OrchestratorDeps['ctx']['agents'];
      effect(fn: () => unknown, label?: string): () => void;
    };

    const isLive = (sessionId: string): boolean => {
      try {
        return !!remoteCtx.agents.get(sessionId);
      } catch {
        return false;
      }
    };

    // HB-19 (2026-10-17): a Map, not an object literal. `endpoints[verb]` on a
    // plain object also resolves inherited keys ("constructor", "toString",
    // "__proto__"), so a crafted verb could reach something that was never
    // registered as an endpoint. Map.get has no prototype chain.
    const endpoints = new Map<string, Endpoint>(Object.entries(buildEndpoints(deps, isLive)));

    // ── H-41 (2026-10-07): explicit dependency on the host's /api gate ────
    // This route is mounted under the host's `/api` prefix, and that prefix's
    // check is the ONLY authentication it has — the plugin keeps no credential
    // of its own. The host implements it as `connection.admit(req)`, which
    // returns `requestRejection(req)`'s verdict (Host/Origin fence + the
    // browser-auth secret; the `/api` prefix route calls it before dispatching,
    // so this exact path can never be reached without it). If a future host
    // drops or renames that check, the destructive endpoints above would be
    // reachable by anything that can POST to loopback — so fail closed on them
    // instead of guessing, and say so in the audit log once at registration.
    const gate = remoteCtx.connection as unknown as { admit?: unknown; requestRejection?: unknown };
    const hostGuarded = typeof gate.admit === 'function' || typeof gate.requestRejection === 'function';
    if (!hostGuarded) {
      try {
        appendAuditLine(deps.guard.assert(deps.paths.logsDir + '/heartbeat.jsonl'), {
          event: 'rpc_host_gate_missing',
          detail: 'connection.admit/requestRejection absent; all but the low-sensitivity read-only verbs are refused (⑦A)',
          allowed: [...GATE_SAFE_ENDPOINTS],
        });
      } catch { /* 审计失败不影响注册 */ }
    }

    const handler = async (endpoint: unknown, payload: unknown): Promise<RpcResult> => {
      const p = (payload ?? {}) as Record<string, unknown>;
      const fn = typeof endpoint === 'string' ? endpoints.get(endpoint) : undefined;
      if (!fn) return err('bad-request', `unknown endpoint ${JSON.stringify(endpoint)}`);
      if (!hostGuarded && !GATE_SAFE_ENDPOINTS.has(endpoint as string)) {
        return err('forbidden', `host gate unavailable; ${endpoint} is refused (H-41, ⑦A)`);
      }
      try {
        return await fn(p);
      } catch (e) {
        return err('internal', String(e).slice(0, 200));
      }
    };

    // RPC 信封与 /api 通道的 client-request/server-response 同构（客户端仍是
    // connection.rpc.call），端点名改走 payload.endpoint 字段。
    remoteCtx.effect(
      () => remoteCtx.connection.fetch.register({
        path: RPC_ROUTE_PATH,
        methods: ['POST'],
        requestBody: 'buffered',
        fetch: async (request: Request): Promise<Response> => {
          let envelope: { type?: unknown; rpcId?: unknown; payload?: unknown };
          try {
            envelope = await request.json() as typeof envelope;
          } catch {
            return new Response('body is not JSON', { status: 400 });
          }
          const rpcId = envelope?.rpcId;
          if (envelope?.type !== 'client-request' || typeof rpcId !== 'string' || typeof envelope.payload !== 'object' || envelope.payload === null) {
            return new Response('invalid envelope', { status: 400 });
          }
          const p = envelope.payload as Record<string, unknown>;
          const endpoint = typeof p.endpoint === 'string' ? p.endpoint : '(missing endpoint)';
          const result = await handler(endpoint, p);
          return Response.json({ type: 'server-response', rpcId, result });
        },
      }),
      'heartbeat: rpc route',
    );
    ctx.logger.info('heartbeat: rpc route ready (%s)', RPC_ROUTE_PATH);
    try {
      appendAuditLine(deps.guard.assert(deps.paths.logsDir + '/heartbeat.jsonl'), { event: 'rpc_registered', route: RPC_ROUTE_PATH });
    } catch { /* 审计失败不影响注册 */ }
  });
}
